def choose_move(observation):
    # Defensive defaults
    x = observation.get("player_x", 0)
    y = observation.get("player_y", 0)
    grid = observation.get("grid", {})
    # Initialize move to stay in place
    dx = 0
    dy = 0

    # Helper safely get neighboring cell contents
    def cell(dx_off, dy_off):
        return grid.get((x + dx_off, y + dy_off))

    # Priority 1: Resource collection - move toward nearest resource if present
    # Scan in a small radius for resources ('resource', 'R')
    best_r = None
    best_dist = float('inf')
    for (gx, gy), val in grid.items():
        if val in ("resource", "R"):
            dist = abs(gx - x) + abs(gy - y)
            if dist < best_dist:
                best_dist = dist
                best_r = (gx, gy)
    if best_r is not None and best_dist > 0:
        tx, ty = best_r
        dx = (tx - x)
        dy = (ty - y)
        if abs(dx) > 1:
            dx = (dx > 0) - (dx < 0)
        if abs(dy) > 1:
            dy = (dy > 0) - (dy < 0)
        # Normalize to -1,0,1
        if dx != 0 and dy != 0:
            # Prefer horizontal or vertical first to keep within single-step
            if abs(tx - x) >= abs(ty - y):
                dy = 0
            else:
                dx = 0
        return [dx, dy]

    # Priority 2: Pursuit/Evasion - simple chase toward enemy if nearby, else away from nearest threat
    # Look for "enemy" or "threat" markers
    neigh_enemy = None
    min_dist = float('inf')
    for (gx, gy), val in grid.items():
        if val in ("enemy", "threat"):
            dist = abs(gx - x) + abs(gy - y)
            if dist < min_dist:
                min_dist = dist
                neigh_enemy = (gx, gy)
    if neigh_enemy is not None:
        tx, ty = neigh_enemy
        dx = (tx - x)
        dy = (ty - y)
        # Move away if enemy is very close, otherwise towards
        if min_dist <= 2:
            dx = -(tx - x)
            dy = -(ty - y)
        else:
            dx = (tx - x)
            dy = (ty - y)
        # Normalize
        if dx != 0: dx = (dx > 0) - (dx < 0)
        if dy != 0: dy = (dy > 0) - (dy < 0)
        if dx != 0 and dy != 0:
            if abs(tx - x) >= abs(ty - y):
                dy = 0
            else:
                dx = 0
        return [dx, dy]

    # Priority 3: Territory control - move toward unclaimed/less occupied area
    # If we can move to a cell that seems less occupied
    best_score = float('-inf')
    best_move = (0, 0)
    for vx, vy in ((-1,0),(1,0),(0,-1),(0,1),(0,0)):
        nx, ny = x + vx, y + vy
        # bounds safety via observation
        cell_val = grid.get((nx, ny))
        score = 0
        if cell_val is None:
            score += 1  # empty space favorable
        elif cell_val in ("resource","R"):
            score += 2
        elif cell_val in ("enemy","threat"):
            score -= 2
        # Prefer staying if grid unknown
        if score > best_score:
            best_score = score
            best_move = (vx, vy)
    dx, dy = best_move
    return [dx, dy]

